import {
  createCatalogueUseCases,
  type CatalogueUseCases,
} from '../../application/catalogue/CatalogueModule';
import { createOrderUseCases, type OrderUseCases } from '../../application/orders/OrderModule';
import { InMemoryOrderRepository } from '../persistence/InMemoryOrderRepository';
import { InMemoryProductRepository } from '../persistence/InMemoryProductRepository';
import { RandomIdGenerator } from '../system/RandomIdGenerator';
import { SystemClock } from '../system/SystemClock';
import { CATALOGUE_SEED } from './catalogueSeed';

export interface Container {
  readonly orderUseCases: OrderUseCases;
  readonly catalogueUseCases: CatalogueUseCases;
}

/** Composition root: wires adapters into the use cases and seeds the catalogue. */
export function buildContainer(): Container {
  const orders = new InMemoryOrderRepository();
  const products = new InMemoryProductRepository();

  const catalogueUseCases = createCatalogueUseCases({ products });
  const orderUseCases = createOrderUseCases({
    orders,
    products,
    ids: new RandomIdGenerator(),
    clock: new SystemClock(),
  });

  for (const product of CATALOGUE_SEED) {
    catalogueUseCases.addProduct.execute(product);
  }

  return { orderUseCases, catalogueUseCases };
}

=====SOURCE-END=====

