import { randomBytes } from 'node:crypto';

export interface Environment {
  readonly port: number;
  readonly staffApiKey: string;
  /** True when no key was configured and a one-off key was generated. */
  readonly staffApiKeyGenerated: boolean;
}

const DEFAULT_PORT = 3000;

export function loadEnvironment(env: NodeJS.ProcessEnv = process.env): Environment {
  const rawPort = env['PORT'];
  const port = rawPort === undefined || rawPort === '' ? DEFAULT_PORT : Number(rawPort);
  if (!Number.isInteger(port) || port < 0 || port > 65_535) {
    throw new Error(`PORT must be an integer between 0 and 65535, got '${rawPort ?? ''}'`);
  }

  const configuredKey = env['STAFF_API_KEY'];
  if (configuredKey !== undefined && configuredKey.length > 0) {
    return { port, staffApiKey: configuredKey, staffApiKeyGenerated: false };
  }
  return { port, staffApiKey: randomBytes(24).toString('hex'), staffApiKeyGenerated: true };
}

